#include <bits/stdc++.h>
using namespace std;

int L, R, m;
vector<vector<int>> adj; // adjacency list for left vertices (1-indexed)
vector<int> matchR;      // matchR[r] = l matched to r, or -1
vector<bool> visited;

bool tryKuhn(int u) {
    for (int v : adj[u]) {
        if (visited[v]) continue;
        visited[v] = true;
        if (matchR[v] == -1 || tryKuhn(matchR[v])) {
            matchR[v] = u;
            return true;
        }
    }
    return false;
}

int main() {
    cin >> L >> R >> m;
    adj.assign(L + 1, {});
    matchR.assign(R + 1, -1);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
    }
    int result = 0;
    for (int u = 1; u <= L; u++) {
        visited.assign(R + 1, false);
        if (tryKuhn(u)) result++;
    }
    cout << result << endl;
    return 0;
}

