int L, R, m;
vector<vector<int>> adj;
vector<int> matchR;
vector<bool> visited;

bool tryKuhn(int u) {
    for (int v : adj[u]) {
        if (visited[v]) continue;
        visited[v] = true;
        if (matchR[v] == -1 || tryKuhn(matchR[v])) {
            matchR[v] = u;
            return true;
        }
    }
    return false;
}

int main() {
    cin >> L >> R >> m;
    adj.assign(L + 1, {});
    matchR.assign(R + 1, -1);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
    }
    int result = 0;
    for (int u = 1; u <= L; u++) {
        visited.assign(R + 1, false);
        if (tryKuhn(u)) result++;
    }
    cout << result << "\n";
    vector<pair<int,int>> pairs;
    for (int v = 1; v <= R; v++) {
        if (matchR[v] != -1) pairs.push_back({matchR[v], v});
    }
    sort(pairs.begin(), pairs.end());
    for (auto& p : pairs) cout << p.first << " " << p.second << "\n";
    return 0;
}
